//! Help-text quality gates (issue #608).
//!
//! These pin the user-facing `--help` polish the help-text sweep
//! established, so a later edit that reintroduces issue-tracker
//! breadcrumbs, mangles the `--config` TOML example, or lets the
//! `--format` value-name drift back to `<OUTPUT_FORMAT>` fails CI rather
//! than shipping silently. Help is generated by clap at runtime, so the
//! assertions drive the real binary.

use assert_cmd::Command;
use predicates::prelude::*;

use crate::common;

fn cli() -> Command {
    common::bca_command()
}

/// Every subcommand whose `--help` users actually read. The parent
/// `bca --help` and the two `vcs` sub-subcommands are appended in the
/// loop below.
const SUBCOMMANDS: &[&[&str]] = &[
    &["metrics"],
    &["ops"],
    &["vcs"],
    &["report"],
    &["dump"],
    &["find"],
    &["count"],
    &["functions"],
    &["strip-comments"],
    &["preproc"],
    &["list-metrics"],
    &["check"],
    &["init"],
    &["diff-baseline"],
    &["diff"],
    &["exemptions"],
    &["vcs", "commit"],
    &["vcs", "trend"],
];

fn help_for(args: &[&str]) -> String {
    let output = cli()
        .args(args)
        .arg("--help")
        .output()
        .expect("spawn bca --help");
    assert!(
        output.status.success(),
        "`bca {} --help` should exit 0",
        args.join(" ")
    );
    String::from_utf8(output.stdout).expect("help is utf-8")
}

/// The body of one flag's help entry: everything after the rendered
/// `flag_line` up to the blank line that separates it from the next
/// flag. The flag line is matched as a whole line, so a mention of the
/// flag in an earlier entry's prose or in the usage line cannot select
/// the wrong block; pass it exactly as clap renders it, including the
/// `-x, ` short alias when the flag has one. Panics when no such line
/// is rendered, so a renamed flag fails here rather than as a vacuous
/// match on an empty entry.
fn help_entry<'a>(help: &'a str, flag_line: &str) -> &'a str {
    let Some(line) = help.lines().find(|line| line.trim_start() == flag_line) else {
        panic!("help does not render `{flag_line}` as a flag line");
    };
    let anchor = format!("\n{line}\n");
    let (_, after) = help
        .split_once(&anchor)
        .expect("a rendered help line is findable by its own text");
    after.split("\n\n").next().expect("non-empty help entry")
}

/// Scan `text` for a `#NNN` issue breadcrumb — a `#` immediately
/// followed by 2-4 digits. Version-like `1.2.3` text has no `#`, so it is
/// never matched. Returns the offending `#NNN` slice for the panic
/// message.
fn find_issue_reference(text: &str) -> Option<String> {
    let bytes = text.as_bytes();
    for (idx, &b) in bytes.iter().enumerate() {
        if b != b'#' {
            continue;
        }
        let digits = bytes[idx + 1..]
            .iter()
            .take_while(|c| c.is_ascii_digit())
            .count();
        if (2..=4).contains(&digits) {
            return Some(text[idx..idx + 1 + digits].to_string());
        }
    }
    None
}

/// No issue-tracker breadcrumb (`#539`, `issue #328`, `pre-#182`) may
/// reach user-facing help. They are provenance for maintainers and live
/// in `//` comments, never in the clap doc-comments clap renders.
#[test]
fn help_text_carries_no_issue_references() {
    let mut targets: Vec<Vec<&str>> = SUBCOMMANDS.iter().map(|s| s.to_vec()).collect();
    targets.push(Vec::new()); // the top-level `bca --help`

    for args in &targets {
        let help = help_for(args);
        let label = if args.is_empty() {
            "bca".to_string()
        } else {
            format!("bca {}", args.join(" "))
        };
        if let Some(found) = find_issue_reference(&help) {
            panic!(
                "`{label} --help` leaks issue reference {found:?}; move it into a `//` maintainer comment"
            );
        }
    }
}

/// The same `--format` flag must read `<FORMAT>` everywhere — the three
/// `output_format`-backed stragglers (`metrics` / `ops` / `check
/// --report-format`) used to leak the field name as `<OUTPUT_FORMAT>`.
#[test]
fn format_flags_use_format_value_name() {
    for (args, flag) in [
        (&["metrics"][..], "--format <FORMAT>"),
        (&["ops"][..], "--format <FORMAT>"),
        (&["check"][..], "--report-format <FORMAT>"),
    ] {
        let help = help_for(args);
        assert!(
            help.contains(flag),
            "`bca {} --help` should render `{flag}`, not `<OUTPUT_FORMAT>`",
            args.join(" ")
        );
        assert!(
            !help.contains("<OUTPUT_FORMAT>"),
            "`bca {} --help` still leaks the `<OUTPUT_FORMAT>` field name",
            args.join(" ")
        );
    }
}

/// The exit-code prose names the live `--exit-codes=tiered` spelling.
/// `--strict-exit-codes` is the hidden deprecated alias: clap omits its
/// own entry from the flag list, so the only way it can reach help is
/// through hand-written prose, which is what this guards.
#[test]
fn exit_code_help_names_live_tiered_flag() {
    for args in [&[][..], &["check"][..]] {
        let help = help_for(args);
        assert!(
            help.contains("--exit-codes=tiered"),
            "`bca {} --help` should name `--exit-codes=tiered`",
            args.join(" ")
        );
        assert!(
            !help.contains("--strict-exit-codes"),
            "`bca {} --help` names the deprecated `--strict-exit-codes` alias",
            args.join(" ")
        );
    }
}

/// `--report-suppressed` must send readers to the `check` flag that
/// actually selects the SARIF dialect (`--report-format`), not to the
/// deprecated `--format` alias.
#[test]
fn report_suppressed_help_names_report_format() {
    let help = help_for(&["check"]);
    let entry = help_entry(&help, "--report-suppressed");
    assert!(
        entry.contains("--report-format sarif"),
        "`--report-suppressed` text should name `--report-format sarif`: {entry}"
    );
    assert!(
        !entry.contains("`--format"),
        "`--report-suppressed` text still names the deprecated `--format` alias: {entry}"
    );
}

/// The `-t/--type` entry on `find` and `count` names every semantic
/// filter the option accepts — the six `match` arms in the
/// `ParserTrait::filters` impl that win over a same-named node type — and
/// points at the book section defining them. The entry is selected by
/// its rendered flag line and cut at the next blank line, and the count
/// of filter words is pinned so a missing one cannot hide behind the
/// others.
#[test]
fn node_type_help_names_the_semantic_filters() {
    const FILTERS: [&str; 6] = ["all", "function", "call", "comment", "string", "error"];
    for subcommand in ["find", "count"] {
        let help = help_for(&[subcommand]);
        let entry = help_entry(&help, "-t, --type <NODE_TYPE>");
        let named = FILTERS
            .iter()
            .filter(|filter| entry.contains(&format!("`{filter}`")))
            .count();
        assert_eq!(
            named,
            FILTERS.len(),
            "`bca {subcommand} --help` `--type` entry should name all six semantic filters: {entry}"
        );
        assert!(
            entry.contains("commands/nodes.html#semantic-filters"),
            "`bca {subcommand} --help` `--type` entry should link the book's semantic-filters section: {entry}"
        );
    }
}

/// The `--config` example must render as a readable indented block, not
/// the one-line smashed Markdown fence clap produced before
/// `verbatim_doc_comment` was applied.
#[test]
fn check_config_example_renders_as_block() {
    cli()
        .args(["check", "--help"])
        .assert()
        .success()
        // The table rows land on their own indented lines.
        .stdout(predicate::str::contains("    [thresholds]\n"))
        .stdout(predicate::str::contains("    cyclomatic = 15\n"))
        // The raw Markdown fence must never reach the rendered help.
        .stdout(predicate::str::contains("```").not());
}
